export function getTanosWordsByLevel(level: JLPTLevel): JLPTWord[] {
  switch (level) {
    case "N5": return TANOS_N5_WORDS;
    case "N4": return TANOS_N4_WORDS;
    case "N3": return TANOS_N3_WORDS;
    case "N2": return TANOS_N2_WORDS;
    case "N1": return TANOS_N1_WORDS;
    default: return TANOS_N5_WORDS;
  }
}

export const ALL_TANOS_WORDS: JLPTWord[] = [
  ...TANOS_N5_WORDS,
  ...TANOS_N4_WORDS,
  ...TANOS_N3_WORDS,
  ...TANOS_N2_WORDS,
  ...TANOS_N1_WORDS,
];
